// A stand-in for PrusaSlicer in tests: it writes G-code with the statistics a real one ends with, or refuses a part
// whose file name says it is too big, the way a slicer refuses a part that doesn't fit the bed.
import { readFileSync, writeFileSync } from 'node:fs';

const args = process.argv.slice(2);
const out = args[args.indexOf('--output') + 1];
const files = args.filter((a) => a.endsWith('.stl'));
if (!out || !files.length) {
  console.error('error: nothing to slice');
  process.exit(2);
}
let triangles = 0;
for (const f of files) triangles += readFileSync(f).readUInt32LE(80);
if (args.includes('--max-print-height') && Number(args[args.indexOf('--max-print-height') + 1]) < 30) {
  console.error('Objects could not fit on the bed');
  process.exit(1);
}
const cost = Number(args[args.indexOf('--filament-cost') + 1]);
const grams = 5.73;
writeFileSync(
  out,
  [
    '; generated by a stand-in slicer',
    ...Array.from({ length: 119 }, (_, i) => `;LAYER_CHANGE\n;Z:${(i + 1) * 0.2}`),
    `; ${triangles} triangles in ${files.length} parts`,
    `; filament used [g] = ${grams}`,
    `; total filament used [g] = ${grams}`,
    `; total filament cost = ${((grams * cost) / 1000).toFixed(2)}`,
    '; estimated printing time (normal mode) = 46m 26s',
    '',
  ].join('\n'),
);
